CardSets.register({"id":"star-wars","name":"Star Wars","code":"WARS","description":"420 cards from a galaxy far, far away — Jedi and Sith, rebels and empires, droids, starships, worlds, weapons, and the films and battles that made them legend.","theme":{"primary":"#11131a","secondary":"#ffe81f","artBackground":"#0b0e17","artFit":"cover"},"pack":{"name":"Star Wars Pack","emblem":"🌌","skin":"star-wars"},"cards":[{"name":"Darth Vader","rarity":"chase","id":"darth-vader","subtitle":"Villains & Empire","details":"Once Jedi Knight Anakin Skywalker, Darth Vader serves Emperor Palpatine as a Sith Lord, hunting Jedi survivors in black armor and a cape.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/de/DarthVader-TheEmpire2026.png/revision/latest?cb=20260522041242"},{"name":"Luke Skywalker","rarity":"chase","id":"luke-skywalker","subtitle":"Heroes & Rebels","details":"A Tatooine farm boy who becomes a Jedi Knight, Luke Skywalker destroys the first Death Star and helps redeem his father, Darth Vader.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3d/LukeSkywalker.png/revision/latest/scale-to-width-down/450?cb=20241221010122"},{"name":"Yoda","rarity":"chase","id":"yoda","subtitle":"Heroes & Rebels","details":"A wise Jedi Master centuries old, Yoda trains generations of Jedi and guides Luke Skywalker on Dagobah with lessons in patience and the Force.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d6/Yoda_SWSB.png/revision/latest/scale-to-width-down/500?cb=20150206140125"},{"name":"Millennium Falcon","rarity":"chase","id":"millennium-falcon","subtitle":"Starships & Vehicles","details":"A modified YT-1300 freighter piloted by Han Solo and Chewbacca, the Millennium Falcon makes the Kessel Run in less than twelve parsecs.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/52/Millennium_Falcon_Fathead_TROS.png/revision/latest/scale-to-width-down/600?cb=20221029015218"},{"name":"Han Solo","rarity":"chase","id":"han-solo","subtitle":"Heroes & Rebels","details":"A Corellian smuggler turned Rebel hero, Han Solo pilots the Millennium Falcon, aids the Death Star rescue, and fights beside Leia and Luke.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e2/TFAHanSolo.png/revision/latest/scale-to-width-down/450?cb=20160208055002"},{"name":"Leia Organa","rarity":"chase","id":"leia-organa","subtitle":"Heroes & Rebels","details":"Princess of Alderaan, Rebel leader, and later Resistance general, Leia Organa is a fearless senator, strategist, and Force-sensitive hero.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f1/Leia_Organa_TROS.png/revision/latest/scale-to-width-down/450?cb=20200102034101"},{"name":"Obi-Wan Kenobi","rarity":"chase","id":"obi-wan-kenobi","subtitle":"Heroes & Rebels","details":"Jedi Knight and later Master, Obi-Wan Kenobi trains Anakin and Luke Skywalker, duels Darth Vader, and watches over Luke from exile on Tatooine.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/4e/ObiWanHS-SWE.jpg/revision/latest/scale-to-width-down/450?cb=20111115052816"},{"name":"Chewbacca","rarity":"chase","id":"chewbacca","subtitle":"Heroes & Rebels","details":"A loyal Wookiee warrior from Kashyyyk, Chewbacca serves as co-pilot of the Millennium Falcon and a steadfast friend to Han Solo and the Rebels.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/25/Chewbacca-SWBC5cvr.png/revision/latest/scale-to-width-down/450?cb=20260426033709"},{"name":"R2-D2","rarity":"chase","id":"r2-d2","subtitle":"Droids","details":"A brave astromech droid, R2-D2 carries the Death Star plans, serves Anakin, Luke, and Leia, and saves his friends with tools and quick thinking.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/95/R2-D2-TROSOCE.png/revision/latest/scale-to-width-down/396?cb=20240104043013"},{"name":"Emperor Palpatine","rarity":"chase","id":"emperor-palpatine","subtitle":"Villains & Empire","details":"Secretly Sith Lord Darth Sidious, Palpatine rises from senator to Emperor, corrupts Anakin Skywalker, and rules the Empire through fear and the Force.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e2/Palpatine-CEUEEd.png/revision/latest/scale-to-width-down/500?cb=20250105171652"},{"name":"Anakin Skywalker","rarity":"legendary","id":"anakin-skywalker","subtitle":"Heroes & Rebels","details":"A gifted Jedi Knight and podracer from Tatooine, Anakin Skywalker fights in the Clone Wars before his fear and anger lead him toward the dark side.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/6f/Anakin_Skywalker_RotS.png/revision/latest/scale-to-width-down/480?cb=20130621175844"},{"name":"Ahsoka Tano","rarity":"legendary","id":"ahsoka-tano","subtitle":"Heroes & Rebels","details":"Anakin Skywalker's Togruta Padawan, Ahsoka Tano leaves the Jedi Order, fights for the Rebellion, and wields two lightsabers with white blades.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/27/Ahsoka-Tano-AG-2023.png/revision/latest/scale-to-width-down/459?cb=20231009063143"},{"name":"Din Djarin","rarity":"legendary","id":"din-djarin","subtitle":"Heroes & Rebels","details":"A Mandalorian bounty hunter in beskar armor, Din Djarin protects Grogu, follows the Way of the Mandalore, and pilots the Razor Crest across the galaxy.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/46/DinDjarinArmor-CGSWG.png/revision/latest/scale-to-width-down/483?cb=20241206044557"},{"name":"Grogu","rarity":"legendary","id":"grogu","subtitle":"Heroes & Rebels","details":"A Force-sensitive foundling of Yoda's species, Grogu trains briefly with Luke Skywalker and travels under the protection of Din Djarin, the Mandalorian.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/06/Grogu-BoBFBox.png/revision/latest/scale-to-width-down/600?cb=20251105060853"},{"name":"Rey","rarity":"legendary","id":"rey","subtitle":"Heroes & Rebels","details":"A scavenger from Jakku, Rey discovers the Force, trains under Leia Organa, confronts Kylo Ren, and claims the Skywalker name to honor her teachers.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2b/Rey_TROS_Fathead.png/revision/latest/scale-to-width-down/391?cb=20231113074423"},{"name":"Padmé Amidala","rarity":"legendary","id":"padme-amidala","subtitle":"Heroes & Rebels","details":"Queen and then senator of Naboo, Padmé Amidala champions diplomacy and justice, fights for the Republic, and loves Anakin Skywalker in secret.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b2/Padmegreenscrshot.jpg/revision/latest/scale-to-width-down/412?cb=20100423143631"},{"name":"Mace Windu","rarity":"legendary","id":"mace-windu","subtitle":"Heroes & Rebels","details":"A senior Jedi Master with a purple lightsaber, Mace Windu leads the Jedi Council in the Clone Wars and duels Chancellor Palpatine on Coruscant.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/27/MaceWindu_-WoSW.png/revision/latest/scale-to-width-down/473?cb=20220914013358"},{"name":"Qui-Gon Jinn","rarity":"legendary","id":"qui-gon-jinn","subtitle":"Heroes & Rebels","details":"An independent Jedi Master, Qui-Gon Jinn discovers Anakin Skywalker on Tatooine and believes the boy is the prophesied Chosen One of Jedi lore.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f6/Qui-Gon_Jinn_Headshot_TPM.jpg/revision/latest/scale-to-width-down/439?cb=20180430174809"},{"name":"Lando Calrissian","rarity":"legendary","id":"lando-calrissian","subtitle":"Heroes & Rebels","details":"A smooth smuggler and administrator of Cloud City, Lando Calrissian joins the Rebellion, pilots the Millennium Falcon, and helps destroy Death Star II.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/29/LandoCalrissian-TROSOCE.png/revision/latest/scale-to-width-down/450?cb=20200101050952"},{"name":"Cassian Andor","rarity":"legendary","id":"cassian-andor","subtitle":"Heroes & Rebels","details":"A Rebel intelligence officer, Cassian Andor undertakes covert missions against the Empire and joins Jyn Erso to steal the Death Star plans on Scarif.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/31/CassianAndor-Fathead.png/revision/latest/scale-to-width-down/450?cb=20161108051806"},{"name":"Darth Maul","rarity":"legendary","id":"darth-maul","subtitle":"Villains & Empire","details":"A Zabrak Sith apprentice from Dathomir, Darth Maul wields a double-bladed lightsaber, survives his duel with Obi-Wan, and builds a criminal empire.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/89/MaulHS_SWI185.png/revision/latest/scale-to-width-down/450?cb=20181108061212"},{"name":"Count Dooku","rarity":"legendary","id":"count-dooku","subtitle":"Villains & Empire","details":"A former Jedi Master turned Sith Lord Darth Tyranus, Count Dooku leads the Separatists in the Clone Wars and duels Yoda, Obi-Wan, and Anakin.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/5f/Dooku-SWBC61.png/revision/latest/scale-to-width-down/450?cb=20241118020049"},{"name":"Grand Admiral Thrawn","rarity":"legendary","id":"grand-admiral-thrawn","subtitle":"Villains & Empire","details":"A brilliant Chiss Imperial strategist, Grand Admiral Thrawn studies art and culture to outthink his enemies, posing a grave threat to the New Republic.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fe/Thrawn_Character_poster.png/revision/latest/scale-to-width-down/450?cb=20260325022606"},{"name":"Boba Fett","rarity":"legendary","id":"boba-fett","subtitle":"Villains & Empire","details":"A clone of Jango Fett and a famed bounty hunter in Mandalorian armor, Boba Fett captures Han Solo for Jabba and later rules Tatooine's underworld.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/62/BobaFettHS-SWI213.png/revision/latest/scale-to-width-down/473?cb=20250317160100"},{"name":"Jabba the Hutt","rarity":"legendary","id":"jabba-the-hutt","subtitle":"Villains & Empire","details":"A powerful Hutt crime lord on Tatooine, Jabba the Hutt runs smuggling and bounty operations from his palace, keeping Han Solo frozen in carbonite.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fe/Jabba_MMSWCA.png/revision/latest/scale-to-width-down/492?cb=20231031040818"},{"name":"Kylo Ren","rarity":"legendary","id":"kylo-ren","subtitle":"Villains & Empire","details":"Born Ben Solo, Kylo Ren turns to the dark side under Snoke, leads the Knights of Ren, and is drawn back to the light through Leia, Han, and Rey.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a8/KyloRenHelmeted-TROS.png/revision/latest?cb=20250126001318"},{"name":"Supreme Leader Snoke","rarity":"legendary","id":"supreme-leader-snoke","subtitle":"Villains & Empire","details":"A powerful dark side figure who leads the First Order, Supreme Leader Snoke corrupts Ben Solo and is struck down by Kylo Ren aboard his flagship.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f0/Snoke-TLJOCE.png/revision/latest/scale-to-width-down/450?cb=20221204063658"},{"name":"Moff Gideon","rarity":"legendary","id":"moff-gideon","subtitle":"Villains & Empire","details":"An Imperial warlord after the Empire's fall, Moff Gideon hunts Grogu for his blood, wields the Darksaber, and clashes with Din Djarin repeatedly.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/16/Gideon_Armored.png/revision/latest/scale-to-width-down/439?cb=20251102175525"},{"name":"C-3PO","rarity":"legendary","id":"c-3po","subtitle":"Droids","details":"A protocol droid built by young Anakin Skywalker, C-3PO is fluent in over six million forms of communication and serves the Skywalker family faithfully.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a2/C-3PO-TROSTGG.png/revision/latest/scale-to-width-down/450?cb=20230706042830"},{"name":"BB-8","rarity":"legendary","id":"bb-8","subtitle":"Droids","details":"A loyal spherical astromech droid belonging to Poe Dameron, BB-8 carries a vital map fragment and rolls into danger beside Rey, Finn, and the Resistance.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/68/BB8-Fathead.png/revision/latest/scale-to-width-down/420?cb=20161108050455"},{"name":"Death Star","rarity":"legendary","id":"death-star","subtitle":"Starships & Vehicles","details":"A moon-sized Imperial battle station armed with a planet-destroying superlaser, the Death Star is destroyed by Luke Skywalker at the Battle of Yavin.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/70/DSI-HDapproach.png/revision/latest/scale-to-width-down/600?cb=20130221005853"},{"name":"X-Wing Starfighter","rarity":"legendary","id":"x-wing-starfighter","subtitle":"Starships & Vehicles","details":"The Rebellion's versatile starfighter, the X-wing opens its S-foils into an X shape for combat and carries an astromech droid for repairs and navigation.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/00/Xwing-ROOCE.png/revision/latest/scale-to-width-down/600?cb=20230516042654"},{"name":"TIE Fighter","rarity":"legendary","id":"tie-fighter","subtitle":"Starships & Vehicles","details":"The Empire's standard starfighter, the TIE fighter has twin ion engines, hexagonal solar wings, and speed in place of shields, armor, and a hyperdrive.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d1/TIE_Fighter_DICE.png/revision/latest/scale-to-width-down/515?cb=20161021230639"},{"name":"Imperial Star Destroyer","rarity":"legendary","id":"imperial-star-destroyer","subtitle":"Starships & Vehicles","details":"A wedge-shaped Imperial capital ship over a kilometer long, the Star Destroyer carries TIE fighters, troops, and turbolasers across the galaxy in force.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3e/ISD1-SWSVguide.png/revision/latest/scale-to-width-down/600?cb=20240602042313"},{"name":"Slave I","rarity":"legendary","id":"slave-i","subtitle":"Starships & Vehicles","details":"Jango Fett's distinctive patrol craft, later flown by Boba Fett, Slave I carries seismic charges, hidden weapons, and prisoners for bounty hunting work.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/21/BobaFettsStarship-CGSWG.png/revision/latest/scale-to-width-down/486?cb=20241226014039"},{"name":"Razor Crest","rarity":"legendary","id":"razor-crest","subtitle":"Starships & Vehicles","details":"Din Djarin's gunship and home, the Razor Crest carries Grogu and his bounty hunting gear until it is destroyed by Moff Gideon's Imperial forces.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2e/RazorCrest-TSWB.png/revision/latest/scale-to-width-down/600?cb=20260404200334"},{"name":"Tatooine","rarity":"legendary","id":"tatooine","subtitle":"Planets & Locations","details":"A desert planet with twin suns in the Outer Rim, Tatooine is home to Anakin and Luke Skywalker, Mos Eisley spaceport, Tusken Raiders, and moisture farms.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b0/Tatooine_TPM.png/revision/latest/scale-to-width-down/600?cb=20241209041104"},{"name":"Coruscant","rarity":"legendary","id":"coruscant","subtitle":"Planets & Locations","details":"A city-covered planet at the heart of the galaxy, Coruscant hosts the Jedi Temple, the Senate, and the Imperial Palace through successive eras of rule.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/84/CoruscantGlobeE1.png/revision/latest/scale-to-width-down/600?cb=20240513175137"},{"name":"Darksaber","rarity":"legendary","id":"darksaber","subtitle":"Weapons, Artifacts & Tech","details":"A unique black-bladed lightsaber created by Tarre Vizsla, the Darksaber is a symbol of Mandalorian leadership claimed by Bo-Katan Kryze and Din Djarin.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/0a/Darksaber-SW100Objects.png/revision/latest/scale-to-width-down/600?cb=20241020054319"},{"name":"Star Wars: Episode IV – A New Hope","rarity":"legendary","id":"star-wars-episode-iv-a-new-hope","subtitle":"Films & Series","details":"The film that begins the saga on screen, A New Hope follows Luke Skywalker, Leia Organa, and Han Solo as the Rebellion destroys the first Death Star.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/44/1977-StarWars-theatricalposter.jpg/revision/latest/scale-to-width-down/392?cb=20260130123909"},{"name":"Poe Dameron","rarity":"epic","id":"poe-dameron","subtitle":"Heroes & Rebels","details":"A daring Resistance X-wing pilot, Poe Dameron leads Black Squadron, helps destroy Starkiller Base, and rises to general alongside Leia Organa's guidance.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/6b/PoeDameron-Heroes2023.png/revision/latest/scale-to-width-down/600?cb=20251128064305"},{"name":"Finn","rarity":"epic","id":"finn","subtitle":"Heroes & Rebels","details":"A former First Order stormtrooper designated FN-2187, Finn defects to the Resistance, befriends Rey and Poe, and helps fight Supreme Leader Snoke's forces.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/1a/Finn-TSWB.png/revision/latest/scale-to-width-down/547?cb=20250106074103"},{"name":"Jyn Erso","rarity":"epic","id":"jyn-erso","subtitle":"Heroes & Rebels","details":"Daughter of Death Star designer Galen Erso, Jyn Erso leads Rogue One to Scarif to steal the battle station plans that reach Princess Leia Organa.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b3/JynErsoPromo.png/revision/latest/scale-to-width-down/401?cb=20180211063950"},{"name":"Kanan Jarrus","rarity":"epic","id":"kanan-jarrus","subtitle":"Heroes & Rebels","details":"A Jedi who survived Order 66, Kanan Jarrus leads the Ghost crew, trains Ezra Bridger, and sacrifices himself to save his friends on Lothal.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f6/Kanan-JediNight.png/revision/latest/scale-to-width-down/450?cb=20241231035454"},{"name":"Ezra Bridger","rarity":"epic","id":"ezra-bridger","subtitle":"Heroes & Rebels","details":"A Force-sensitive orphan from Lothal, Ezra Bridger joins the Ghost crew, trains as a Jedi under Kanan Jarrus, and vanishes with Grand Admiral Thrawn.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/ad/Ezra_Bridger_character_poster.png/revision/latest/scale-to-width-down/450?cb=20260201003755"},{"name":"Hera Syndulla","rarity":"epic","id":"hera-syndulla","subtitle":"Heroes & Rebels","details":"A Twi'lek pilot and Rebel leader, Hera Syndulla captains the Ghost, leads Phoenix Squadron, and becomes a general in the fight against the Empire.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/cc/MaryElizabethWinsteadasHeraSyndulla-ToppsChoice2025.png/revision/latest/scale-to-width-down/480?cb=20251206225907"},{"name":"Sabine Wren","rarity":"epic","id":"sabine-wren","subtitle":"Heroes & Rebels","details":"A Mandalorian artist and weapons expert, Sabine Wren joins the Ghost crew, wields the Darksaber for a time, and later searches for Ezra Bridger.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/cc/Sabine_Wren-AG.png/revision/latest/scale-to-width-down/480?cb=20241217034612"},{"name":"Mon Mothma","rarity":"epic","id":"mon-mothma","subtitle":"Heroes & Rebels","details":"A senator from Chandrila, Mon Mothma helps build the Rebel Alliance in secrecy and later leads the New Republic as its first chancellor after the Empire.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/22/Mon_Mothma_Ahsoka_poster.png/revision/latest/scale-to-width-down/450?cb=20230904071259"},{"name":"Bail Organa","rarity":"epic","id":"bail-organa","subtitle":"Heroes & Rebels","details":"Senator of Alderaan and a founder of the Rebellion, Bail Organa adopts Leia, aids surviving Jedi, and supports the Alliance until Alderaan's destruction.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b0/Bailrogueone.jpg/revision/latest/scale-to-width-down/435?cb=20241219201015"},{"name":"Wedge Antilles","rarity":"epic","id":"wedge-antilles","subtitle":"Heroes & Rebels","details":"A skilled Rebel and Resistance pilot, Wedge Antilles survives the battles against both Death Stars and flies in the final fight against the Final Order.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b2/WedgeAntilles-Masterwork2020.png/revision/latest/scale-to-width-down/471?cb=20241228034128"},{"name":"Admiral Ackbar","rarity":"epic","id":"admiral-ackbar","subtitle":"Heroes & Rebels","details":"A Mon Calamari commander, Admiral Ackbar leads the Rebel fleet at Endor, warns that a trap awaits, and later serves the Resistance against the First Order.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/29/Admiral_Ackbar_RH.png/revision/latest/scale-to-width-down/452?cb=20221224032123"},{"name":"Kit Fisto","rarity":"epic","id":"kit-fisto","subtitle":"Heroes & Rebels","details":"A cheerful Nautolan Jedi Master, Kit Fisto fights in the Clone Wars with a green lightsaber and falls confronting Darth Sidious on Coruscant.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/25/KitFisto-USWNE.png/revision/latest/scale-to-width-down/460?cb=20241201061011"},{"name":"Plo Koon","rarity":"epic","id":"plo-koon","subtitle":"Heroes & Rebels","details":"A wise Kel Dor Jedi Master, Plo Koon wears a breathing mask, flies in the Clone Wars, and helps young Ahsoka Tano join the Jedi Order as a child.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/bf/PloKoonCardTrader.png/revision/latest/scale-to-width-down/600?cb=20251218183946"},{"name":"Captain Rex","rarity":"epic","id":"captain-rex","subtitle":"Heroes & Rebels","details":"Clone Captain Rex serves under Anakin Skywalker and Ahsoka Tano in the 501st Legion, removes his inhibitor chip, and joins the early Rebellion.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/89/Captain_Rex_old.png/revision/latest/scale-to-width-down/450?cb=20250413205834"},{"name":"General Grievous","rarity":"epic","id":"general-grievous","subtitle":"Villains & Empire","details":"A cyborg Separatist general, Grievous collects lightsabers from fallen Jedi, commands droid armies, and duels Obi-Wan Kenobi on Utapau in the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/45/GrievousStand-SWHC821.png/revision/latest/scale-to-width-down/450?cb=20241118020627"},{"name":"Asajj Ventress","rarity":"epic","id":"asajj-ventress","subtitle":"Villains & Empire","details":"A Dathomiri assassin trained by Count Dooku, Asajj Ventress wields twin red lightsabers, survives betrayal, and later works as a bounty hunter.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fb/AsajjVentress-2024Base.png/revision/latest/scale-to-width-down/450?cb=20251026185311"},{"name":"Grand Moff Tarkin","rarity":"epic","id":"grand-moff-tarkin","subtitle":"Villains & Empire","details":"Governor of the Outer Rim and commander of the Death Star, Grand Moff Tarkin rules through fear and orders Alderaan destroyed as a demonstration.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c1/Tarkininfobox.jpg/revision/latest/scale-to-width-down/450?cb=20100620213033"},{"name":"Orson Krennic","rarity":"epic","id":"orson-krennic","subtitle":"Villains & Empire","details":"Director of Imperial weapons research, Orson Krennic oversees construction of the Death Star and clashes with Tarkin, Galen Erso, and the Rebels on Scarif.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/05/OrsonKrennic-SWI171.png/revision/latest/scale-to-width-down/450?cb=20221004010739"},{"name":"Savage Opress","rarity":"epic","id":"savage-opress","subtitle":"Villains & Empire","details":"A Zabrak Nightbrother from Dathomir, Savage Opress serves Count Dooku and later joins his brother Darth Maul before falling to Darth Sidious.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a0/SavageOpress-BTMF74.png/revision/latest/scale-to-width-down/500?cb=20260228041538"},{"name":"The Grand Inquisitor","rarity":"epic","id":"the-grand-inquisitor","subtitle":"Villains & Empire","details":"A former Jedi Temple Guard turned Imperial Inquisitor, the Grand Inquisitor hunts Jedi survivors and duels Kanan Jarrus and Ezra Bridger on Lothal.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/7d/TheGrandInquisitor-SWR.png/revision/latest/scale-to-width-down/600?cb=20260313200114"},{"name":"Dryden Vos","rarity":"epic","id":"dryden-vos","subtitle":"Villains & Empire","details":"A scarred crime lord who leads Crimson Dawn, Dryden Vos forces Han Solo and Qi'ra into a coaxium heist and keeps a collection of rare antiquities.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/75/Dryden_Vos_HS.png/revision/latest/scale-to-width-down/450?cb=20220915032825"},{"name":"Pong Krell","rarity":"epic","id":"pong-krell","subtitle":"Villains & Empire","details":"A Besalisk Jedi General with four arms and twin double-bladed lightsabers, Pong Krell betrays his clone troops on Umbara and is stopped by Captain Rex.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/14/PongKrell-POD.png/revision/latest/scale-to-width-down/450?cb=20121127022534"},{"name":"K-2SO","rarity":"epic","id":"k-2so","subtitle":"Droids","details":"A reprogrammed Imperial security droid, K-2SO aids Cassian Andor and Jyn Erso with blunt honesty and falls defending the Scarif vault during Rogue One.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/23/K2SO-SWBC35cvr.png/revision/latest/scale-to-width-down/554?cb=20241112052810"},{"name":"Chopper (C1-10P)","rarity":"epic","id":"chopper-c1-10p","subtitle":"Droids","details":"A grumpy, aging astromech droid aboard the Ghost, Chopper helps Hera Syndulla and the Spectres on missions against the Empire despite constant complaints.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/bb/Chopper_Live_Action.png/revision/latest/scale-to-width-down/451?cb=20230620225311"},{"name":"IG-11","rarity":"epic","id":"ig-11","subtitle":"Droids","details":"An assassin droid reprogrammed as a nurse droid, IG-11 protects Grogu, serves Din Djarin, and sacrifices himself against Imperial forces on Nevarro.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2c/MarshalIG-11.jpg/revision/latest/scale-to-width-down/600?cb=20230425134709"},{"name":"Y-Wing Starfighter","rarity":"epic","id":"y-wing-starfighter","subtitle":"Starships & Vehicles","details":"A rugged Rebel bomber with twin ion engines, the Y-wing serves from the Clone Wars through the Galactic Civil War despite its aging, maintenance-heavy design.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/9f/YWing-JtRSaV.png/revision/latest/scale-to-width-down/600?cb=20251225190608"},{"name":"A-Wing Starfighter","rarity":"epic","id":"a-wing-starfighter","subtitle":"Starships & Vehicles","details":"The fastest Rebel interceptor, the A-wing trades armor for speed, strikes the Executor at Endor, and later flies for the Resistance against the First Order.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8d/A-wing_DICE.png/revision/latest/scale-to-width-down/600?cb=20161021230115"},{"name":"B-Wing Starfighter","rarity":"epic","id":"b-wing-starfighter","subtitle":"Starships & Vehicles","details":"A heavily armed Rebel assault fighter with a rotating cockpit, the B-wing carries powerful cannons designed to break through Imperial capital ship defenses.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/85/BwingStarfighter-CGSWG.png/revision/latest/scale-to-width-down/443?cb=20250210071035"},{"name":"TIE Interceptor","rarity":"epic","id":"tie-interceptor","subtitle":"Starships & Vehicles","details":"A faster Imperial fighter with dagger-shaped wings and extra cannons, the TIE Interceptor outflies standard TIE fighters in battles such as Endor.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f5/TIE_Interceptor_BF.png/revision/latest/scale-to-width-down/600?cb=20170501054325"},{"name":"Super Star Destroyer","rarity":"epic","id":"super-star-destroyer","subtitle":"Starships & Vehicles","details":"Darth Vader's flagship Executor, a Super Star Destroyer many kilometers long, leads the Imperial fleet until its fall at the Battle of Endor.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a1/Executor2_BF2.png/revision/latest/scale-to-width-down/600?cb=20180903231538"},{"name":"Mon Calamari Cruiser","rarity":"epic","id":"mon-calamari-cruiser","subtitle":"Starships & Vehicles","details":"Converted passenger liners turned Rebel warships, Mon Calamari cruisers shielded Admiral Ackbar's fleet with layered defenses at Endor and beyond.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/73/MonCalamariCruiser-TSWB.png/revision/latest/scale-to-width-down/600?cb=20201021040315"},{"name":"Ghost","rarity":"epic","id":"ghost","subtitle":"Starships & Vehicles","details":"Hera Syndulla's VCX-100 freighter, the Ghost hid a docked Phantom shuttle, carried Spectres on missions, and served as their home in the Rebellion.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/67/Ghost_Destroys_Crystal.png/revision/latest/scale-to-width-down/600?cb=20141028080420"},{"name":"Naboo Royal Starship","rarity":"epic","id":"naboo-royal-starship","subtitle":"Starships & Vehicles","details":"A sleek chromium J-type 327 Nubian, the Naboo Royal Starship carried Queen Amidala from occupied Naboo to Tatooine and onward to Coruscant.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f2/NabooRoyalStarshipTatooine.png/revision/latest/scale-to-width-down/600?cb=20130121220216"},{"name":"Hoth","rarity":"epic","id":"hoth","subtitle":"Planets & Locations","details":"A remote world of ice plains and wampa caves, Hoth hid the Rebels' Echo Base until an Imperial probe droid exposed the shield generator.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/45/BiomesHoth.png/revision/latest/scale-to-width-down/600?cb=20230619040733"},{"name":"Endor","rarity":"epic","id":"endor","subtitle":"Planets & Locations","details":"A forested moon home to Ewoks and towering trees, Endor sheltered the shield generator protecting the second Death Star in orbit above it.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/dd/Endor.png/revision/latest/scale-to-width-down/600?cb=20071217171242"},{"name":"Naboo","rarity":"epic","id":"naboo","subtitle":"Planets & Locations","details":"A peaceful world of lakes, plains and underwater Gungan cities, Naboo was Padmé Amidala's home and the site of a Trade Federation invasion.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/24/NabooFull-SW.png/revision/latest/scale-to-width-down/600?cb=20131223053139"},{"name":"Alderaan","rarity":"epic","id":"alderaan","subtitle":"Planets & Locations","details":"A peaceful, democratic world and Bail Organa's home, Alderaan was destroyed by the first Death Star as a demonstration of Imperial power.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a0/Alderaan_mountains.png/revision/latest/scale-to-width-down/600?cb=20130202022435"},{"name":"Dagobah","rarity":"epic","id":"dagobah","subtitle":"Planets & Locations","details":"A swamp world thick with fog, vines and dark-side echoes, Dagobah was Yoda's place of exile and Luke Skywalker's first training ground.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/17/Dragonsnake_Bog.jpg/revision/latest/scale-to-width-down/600?cb=20091008000655"},{"name":"Anakin's Lightsaber","rarity":"epic","id":"anakins-lightsaber","subtitle":"Weapons, Artifacts & Tech","details":"Built by Anakin Skywalker, this blue-bladed lightsaber passed to Luke, was lost on Bespin, recovered by Maz Kanata, and claimed by Rey.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/48/AnakinSkywalkersLightsaber-CM.png/revision/latest/scale-to-width-down/600?cb=20201129054413"},{"name":"Luke's Green Lightsaber","rarity":"epic","id":"lukes-green-lightsaber","subtitle":"Weapons, Artifacts & Tech","details":"Luke Skywalker built this green-bladed lightsaber before rescuing Han Solo from Jabba, crafting it after losing his father's weapon on Bespin.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/0f/LukeSkywalkersGreenLightsaber-TLJ.jpg/revision/latest/scale-to-width-down/600?cb=20180325234336"},{"name":"Kyber Crystal","rarity":"epic","id":"kyber-crystal","subtitle":"Weapons, Artifacts & Tech","details":"Living crystals attuned to the Force, kyber powers every lightsaber and was mined by the Empire to focus the Death Star's superlaser.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2f/IlumCrystal-SWE.png/revision/latest/scale-to-width-down/600?cb=20131019044038"},{"name":"Tauntaun","rarity":"epic","id":"tauntaun","subtitle":"Creatures & Species","details":"Two-legged snow lizards native to Hoth, tauntauns were ridden by Rebel patrols and gave off enough body heat to shelter a rider in a storm.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/ca/Tauntaun-TCGSfS.png/revision/latest/scale-to-width-down/600?cb=20190527012320"},{"name":"Star Wars: Episode V – The Empire Strikes Back","rarity":"epic","id":"star-wars-episode-v-the-empire-strikes-back","subtitle":"Films & Series","details":"The Rebels scatter after Hoth falls, Luke trains with Yoda on Dagobah, and Vader reveals a shattering truth in the clouds above Bespin.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/4b/Empire-at-40-poster.jpg/revision/latest/scale-to-width-down/600?cb=20250617064525"},{"name":"Star Wars: Episode VI – Return of the Jedi","rarity":"epic","id":"star-wars-episode-vi-return-of-the-jedi","subtitle":"Films & Series","details":"Luke confronts Vader and the Emperor above Endor, the Ewoks join the fight, and the second Death Star falls to the Rebel Alliance fleet.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/57/ROTJStyleAOneSheetPoster.png/revision/latest/scale-to-width-down/600?cb=20250316053811"},{"name":"Battle of Yavin","rarity":"epic","id":"battle-of-yavin","subtitle":"Battles & Iconic Moments","details":"Rebel fighters attacked the Death Star along its trench, and Luke Skywalker, trusting the Force, fired the shot that destroyed the station.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/bd/Battle_of_Yavin.png/revision/latest/scale-to-width-down/600?cb=20220716182807"},{"name":"Battle of Hoth","rarity":"epic","id":"battle-of-hoth","subtitle":"Battles & Iconic Moments","details":"Imperial AT-AT walkers marched on Echo Base as snowspeeders fought to slow them, buying time for Rebel transports to escape into orbit.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/53/At-at.png/revision/latest/scale-to-width-down/600?cb=20130319000914"},{"name":"Aayla Secura","rarity":"rare","id":"aayla-secura","subtitle":"Heroes & Rebels","details":"A blue-skinned Twi'lek Jedi Knight, Aayla Secura led clone troops in the Clone Wars and fought with a blue lightsaber and quick reflexes.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d6/AaylaSecura-TSWB.png/revision/latest/scale-to-width-down/600?cb=20241124035946"},{"name":"Ki-Adi-Mundi","rarity":"rare","id":"ki-adi-mundi","subtitle":"Heroes & Rebels","details":"A Cerean Jedi Master with a tall conical head, Ki-Adi-Mundi sat on the Jedi Council and led clone forces in battles across the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/53/KiAdiMundi1-SWE.png/revision/latest/scale-to-width-down/600?cb=20240203042507"},{"name":"Shaak Ti","rarity":"rare","id":"shaak-ti","subtitle":"Heroes & Rebels","details":"A Togruta Jedi Master with striped montrals, Shaak Ti served on the Jedi Council and oversaw clone training on Kamino during the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/10/ShaakTi-TCW.png/revision/latest/scale-to-width-down/600?cb=20240916001537"},{"name":"Luminara Unduli","rarity":"rare","id":"luminara-unduli","subtitle":"Heroes & Rebels","details":"A Mirialan Jedi Master known for calm discipline, Luminara Unduli fought in the Clone Wars and trained her Padawan Barriss Offee on many missions.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b4/Luminara_CoD.png/revision/latest/scale-to-width-down/600?cb=20120923021235"},{"name":"Barriss Offee","rarity":"rare","id":"barriss-offee","subtitle":"Heroes & Rebels","details":"A Mirialan Padawan trained by Luminara Unduli, Barriss Offee healed and fought in the Clone Wars before turning against the Jedi Temple.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/14/BarrissOffee-TCWForceWarriors.png/revision/latest/scale-to-width-down/600?cb=20260101073036"},{"name":"Commander Cody","rarity":"rare","id":"commander-cody","subtitle":"Heroes & Rebels","details":"Marshal Commander Cody, CC-2224, served loyally under Obi-Wan Kenobi in the 212th Battalion until Order 66 turned him against his general.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f9/CodyPhaseII-TCWCEJtB.png/revision/latest/scale-to-width-down/600?cb=20230707011156"},{"name":"Fives","rarity":"rare","id":"fives","subtitle":"Heroes & Rebels","details":"Clone trooper Fives, CT-5555, served in the 501st Legion, uncovered a hidden conspiracy behind Order 66, and died trying to warn his brothers.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/af/FivesFullARCarmor-SWE.png/revision/latest/scale-to-width-down/600?cb=20160715123652"},{"name":"Echo","rarity":"rare","id":"echo","subtitle":"Heroes & Rebels","details":"Clone trooper Echo survived capture by the Techno Union, gained cybernetic implants, and later joined Clone Force 99, the Bad Batch squad.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/84/EchoNewArmor.png/revision/latest/scale-to-width-down/600?cb=20220102230431"},{"name":"Bodhi Rook","rarity":"rare","id":"bodhi-rook","subtitle":"Heroes & Rebels","details":"An Imperial cargo pilot who defected on Galen Erso's warning, Bodhi Rook guided Rogue One to Jedha, Eadu and finally the vault on Scarif.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/14/BodhiRook-networkconsole.png/revision/latest/scale-to-width-down/600?cb=20220320211147"},{"name":"Chirrut Îmwe","rarity":"rare","id":"chirrut-mwe","subtitle":"Heroes & Rebels","details":"A blind Guardian of the Whills on Jedha, Chirrut Îmwe trusted the Force completely and fought Imperial troops with a staff and lightbow.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/ea/ChirrutStaff.jpg/revision/latest/scale-to-width-down/600?cb=20170307215615"},{"name":"Baze Malbus","rarity":"rare","id":"baze-malbus","subtitle":"Heroes & Rebels","details":"A Guardian of the Whills turned heavy gunner, Baze Malbus protected Chirrut Îmwe and carried a powerful repeating cannon into battle.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/26/BazeJedha.png/revision/latest/scale-to-width-down/600?cb=20240715232627"},{"name":"Saw Gerrera","rarity":"rare","id":"saw-gerrera","subtitle":"Heroes & Rebels","details":"A rebel extremist from Onderon, Saw Gerrera fought the Separatists, then the Empire, using ruthless methods other rebels questioned deeply.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a5/SawGerrera-Masterwork2020.png/revision/latest/scale-to-width-down/600?cb=20251227022531"},{"name":"Jek Porkins","rarity":"rare","id":"jek-porkins","subtitle":"Heroes & Rebels","details":"A Rebel X-wing pilot in Red Squadron, Jek Porkins flew cover during the attack on the first Death Star and was lost in the trench battle.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/67/PorkinsPromo.jpg/revision/latest/scale-to-width-down/600?cb=20081111191616"},{"name":"Biggs Darklighter","rarity":"rare","id":"biggs-darklighter","subtitle":"Heroes & Rebels","details":"Luke Skywalker's friend from Tatooine, Biggs Darklighter joined the Rebellion and flew as Red Three in the attack on the first Death Star.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/db/BiggsDarklighter-SbtDS.png/revision/latest/scale-to-width-down/600?cb=20200618040558"},{"name":"Nien Nunb","rarity":"rare","id":"nien-nunb","subtitle":"Heroes & Rebels","details":"A Sullustan pilot and smuggler, Nien Nunb co-piloted the Millennium Falcon with Lando Calrissian during the attack on the second Death Star.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/25/Nien_Nunb_X-wing.jpg/revision/latest/scale-to-width-down/600?cb=20160224095254"},{"name":"Rose Tico","rarity":"rare","id":"rose-tico","subtitle":"Heroes & Rebels","details":"A Resistance maintenance worker turned hero, Rose Tico fought to save what she loved, freeing fathiers on Canto Bight and battling at Crait.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/9d/RoseAjanKloss-JangoFett1.jpg/revision/latest/scale-to-width-down/600?cb=20240710210257"},{"name":"Maz Kanata","rarity":"rare","id":"maz-kanata","subtitle":"Heroes & Rebels","details":"A wise, Force-sensitive pirate queen over a thousand years old, Maz Kanata ran a castle on Takodana and kept Luke Skywalker's lost lightsaber.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/86/Maz_talking_to_Rey.jpg/revision/latest/scale-to-width-down/600?cb=20160620025859"},{"name":"Lor San Tekka","rarity":"rare","id":"lor-san-tekka","subtitle":"Heroes & Rebels","details":"An elder explorer and friend to Leia Organa, Lor San Tekka held part of the map to Luke Skywalker and was struck down by Kylo Ren on Jakku.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d8/LorSanTekka-SWTimelines.png/revision/latest/scale-to-width-down/600?cb=20241204053044"},{"name":"Cad Bane","rarity":"rare","id":"cad-bane","subtitle":"Villains & Empire","details":"A Duros bounty hunter with a wide-brimmed hat and breathing tubes, Cad Bane outdueled Jedi and clones alike during the Clone Wars era.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/15/CadBaneBlaster-BoBFCh6.png/revision/latest/scale-to-width-down/600?cb=20220210133925"},{"name":"Aurra Sing","rarity":"rare","id":"aurra-sing","subtitle":"Villains & Empire","details":"A pallid bounty hunter and former Jedi Padawan, Aurra Sing mentored young Boba Fett and hunted Jedi for profit during the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/40/AurraSing-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20250222001149"},{"name":"Bossk","rarity":"rare","id":"bossk","subtitle":"Villains & Empire","details":"A Trandoshan bounty hunter who prized Wookiee pelts, Bossk was hired by Darth Vader to hunt the Millennium Falcon after the Battle of Hoth.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/1d/Bossk.png/revision/latest/scale-to-width-down/600?cb=20130219044712"},{"name":"Dengar","rarity":"rare","id":"dengar","subtitle":"Villains & Empire","details":"A scarred Corellian bounty hunter wrapped in bandages, Dengar joined Vader's hunt for the Millennium Falcon and raced swoops in his youth.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3f/Dengar-2025ChromeSapphire.png/revision/latest/scale-to-width-down/600?cb=20251221205047"},{"name":"Zuckuss","rarity":"rare","id":"zuckuss","subtitle":"Villains & Empire","details":"A Gand findsman who tracked prey by intuition and scent, Zuckuss partnered with 4-LOM and answered Darth Vader's call to hunt Han Solo.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/23/Zuckuss.png/revision/latest/scale-to-width-down/600?cb=20150114233850"},{"name":"Jango Fett","rarity":"rare","id":"jango-fett","subtitle":"Villains & Empire","details":"A Mandalorian bounty hunter in beskar armor, Jango Fett became the template for the Republic's clone army and raised his son Boba as his own.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/ad/JangoFett-SWBC20.png/revision/latest/scale-to-width-down/600?cb=20231230051139"},{"name":"Zam Wesell","rarity":"rare","id":"zam-wesell","subtitle":"Villains & Empire","details":"A Clawdite changeling assassin, Zam Wesell tried to kill Padmé Amidala on Coruscant with kouhuns and was silenced by Jango Fett's toxic dart.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/9a/ZamWesell-FF.png/revision/latest/scale-to-width-down/600?cb=20240218200905"},{"name":"Nute Gunray","rarity":"rare","id":"nute-gunray","subtitle":"Villains & Empire","details":"Viceroy of the Trade Federation, Nute Gunray blockaded Naboo at Darth Sidious's urging and helped lead the Separatists in the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/ed/NuteGunray-ALTA.png/revision/latest/scale-to-width-down/600?cb=20251107045823"},{"name":"Rune Haako","rarity":"rare","id":"rune-haako","subtitle":"Villains & Empire","details":"A Neimoidian Trade Federation officer, Rune Haako served as Nute Gunray's nervous advisor during the Naboo blockade and the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/4b/RuneHaako-ALTA.png/revision/latest/scale-to-width-down/600?cb=20251107053143"},{"name":"Admiral Piett","rarity":"rare","id":"admiral-piett","subtitle":"Villains & Empire","details":"Captain Firmus Piett rose to admiral after Vader executed his superior, then commanded the Executor during the hunt for the Rebel fleet.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/13/FirusPiett-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20241127051016"},{"name":"Huyang","rarity":"rare","id":"huyang","subtitle":"Droids","details":"An ancient architect droid who served the Jedi for thousands of years, Huyang taught younglings to build lightsabers aboard the Crucible.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8c/Huyang-AhsokaPoster.png/revision/latest/scale-to-width-down/600?cb=20230826072220"},{"name":"BD-1","rarity":"rare","id":"bd-1","subtitle":"Droids","details":"A small, curious BD-unit explorer droid, BD-1 accompanied Cal Kestis, scanning ruins, opening paths and projecting maps on his journeys.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/16/BD-1_JFO.png/revision/latest/scale-to-width-down/600?cb=20190610025750"},{"name":"R5-D4","rarity":"rare","id":"r5-d4","subtitle":"Droids","details":"A red-and-white astromech droid with a bad motivator, R5-D4's breakdown on Tatooine led the Jawas to sell R2-D2 and C-3PO to Owen Lars instead.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3f/R5D4-AG.png/revision/latest/scale-to-width-down/600?cb=20260117204314"},{"name":"EV-9D9","rarity":"rare","id":"ev-9d9","subtitle":"Droids","details":"A sadistic supervisor droid in Jabba's palace, EV-9D9 assigned R2-D2 and C-3PO to their new duties and oversaw the droid torture chamber.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c3/EV_Droid_The_Mandalorian.png/revision/latest/scale-to-width-down/600?cb=20200623053431"},{"name":"IG-88","rarity":"rare","id":"ig-88","subtitle":"Droids","details":"A towering assassin droid turned bounty hunter, IG-88 answered Darth Vader's summons to hunt the Millennium Falcon and its crew after Hoth.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fe/IG-88B-TESB40.png/revision/latest/scale-to-width-down/600?cb=20211224193425"},{"name":"AT-AT Walker","rarity":"rare","id":"at-at-walker","subtitle":"Starships & Vehicles","details":"All Terrain Armored Transports walked on four legs, carrying troops and heavy cannons through the snow in the Imperial assault on Hoth.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/16/AT-AT_2_Fathead.png/revision/latest/scale-to-width-down/600?cb=20161108042721"},{"name":"AT-ST Walker","rarity":"rare","id":"at-st-walker","subtitle":"Starships & Vehicles","details":"All Terrain Scout Transports were two-legged Imperial walkers used for patrol and support, toppled by Ewok traps during the Battle of Endor.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/ff/ATST-SWBdice.png/revision/latest/scale-to-width-down/600?cb=20230723050455"},{"name":"Snowspeeder","rarity":"rare","id":"snowspeeder","subtitle":"Starships & Vehicles","details":"Rebel T-47 airspeeders adapted for Hoth's cold, snowspeeders used harpoon and tow cables to trip AT-AT walkers during the evacuation.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/44/T-47_Speeder_DICE.png/revision/latest/scale-to-width-down/600?cb=20230723013701"},{"name":"Landspeeder","rarity":"rare","id":"landspeeder","subtitle":"Starships & Vehicles","details":"Luke Skywalker's X-34 landspeeder skimmed over Tatooine's sands on repulsorlifts, carrying him, Ben Kenobi and the droids to Mos Eisley.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/be/X-34-TGTB.png/revision/latest/scale-to-width-down/600?cb=20251217194807"},{"name":"Speeder Bike","rarity":"rare","id":"speeder-bike","subtitle":"Starships & Vehicles","details":"74-Z speeder bikes carried scout troopers through Endor's forests at high speed, weaving between trees in a chase with Luke and Leia.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/47/Speeder_Bike_DICE.png/revision/latest/scale-to-width-down/600?cb=20230723010519"},{"name":"Podracer","rarity":"rare","id":"podracer","subtitle":"Starships & Vehicles","details":"Rebuilt from spare parts by young Anakin Skywalker, his podracer won the Boonta Eve Classic and earned him freedom from slavery on Tatooine.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f7/GasganoPodracer-NTIP.png/revision/latest/scale-to-width-down/600?cb=20251117000813"},{"name":"Jedi Starfighter","rarity":"rare","id":"jedi-starfighter","subtitle":"Starships & Vehicles","details":"Agile Delta-7 and Eta-2 starfighters carried Jedi like Obi-Wan and Anakin in the Clone Wars, relying on astromech droids and the Force.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c1/OWKDelta7Starfighter-Platinum2022.png/revision/latest/scale-to-width-down/600?cb=20241019013821"},{"name":"ARC-170 Starfighter","rarity":"rare","id":"arc-170-starfighter","subtitle":"Starships & Vehicles","details":"A three-seat Republic fighter with a pilot, gunner and astromech, the ARC-170 escorted missions and dueled droid fighters in the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/ba/ARC170starfighter.jpg/revision/latest/scale-to-width-down/600?cb=20111112062600"},{"name":"V-Wing Starfighter","rarity":"rare","id":"v-wing-starfighter","subtitle":"Starships & Vehicles","details":"A compact Republic fighter flown by clone pilots late in the Clone Wars, the V-wing escorted Chancellor Palpatine's shuttle to Coruscant.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a9/V-wing_BF2.png/revision/latest/scale-to-width-down/600?cb=20170825000555"},{"name":"Clone Turbo Tank","rarity":"rare","id":"clone-turbo-tank","subtitle":"Starships & Vehicles","details":"A massive ten-wheeled HAVw A6 Juggernaut, the clone turbo tank rolled troops and cannons across battlefields like Kashyyyk and Felucia.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/81/HAVwA6Juggernauts-SWBoL.png/revision/latest/scale-to-width-down/600?cb=20230806162213"},{"name":"AT-TE Walker","rarity":"rare","id":"at-te-walker","subtitle":"Starships & Vehicles","details":"All Terrain Tactical Enforcers walked on six legs, carrying clone troops and a heavy cannon in the first Battle of Geonosis and beyond.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/60/ATTE-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20250404044201"},{"name":"Sandcrawler","rarity":"rare","id":"sandcrawler","subtitle":"Starships & Vehicles","details":"Huge treaded Jawa fortresses, sandcrawlers crawled Tatooine's deserts collecting scrap and droids to sell to moisture farmers like Owen Lars.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/4a/Sandcrawler-Platinum2025.png/revision/latest/scale-to-width-down/600?cb=20251228052305"},{"name":"Bespin","rarity":"rare","id":"bespin","subtitle":"Planets & Locations","details":"A gas giant mined for tibanna gas, Bespin held Cloud City in its clouds, where Lando Calrissian made a deal that trapped Han Solo's friends.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/11/Bespin-SWCT.png/revision/latest/scale-to-width-down/600?cb=20181010054421"},{"name":"Mustafar","rarity":"rare","id":"mustafar","subtitle":"Planets & Locations","details":"A volcanic world of lava rivers and mining platforms, Mustafar was where Anakin Skywalker fell to Darth Vader in a duel with Obi-Wan Kenobi.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/61/Mustafar-TROSGG.png/revision/latest/scale-to-width-down/600?cb=20200722072411"},{"name":"Scarif","rarity":"rare","id":"scarif","subtitle":"Planets & Locations","details":"A tropical Imperial archive world ringed by a shield gate, Scarif held the Death Star plans that Rogue One stole at the cost of their lives.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/6d/Scarif_SWCT.png/revision/latest/scale-to-width-down/600?cb=20181010053537"},{"name":"Jakku","rarity":"rare","id":"jakku","subtitle":"Planets & Locations","details":"A desert junkyard world of wrecked starships, Jakku was where scavenger Rey lived in an AT-AT shell and first met Finn and BB-8 in the dunes.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/ff/Jakku-PoeDameronFlightLog.png/revision/latest/scale-to-width-down/600?cb=20251031044441"},{"name":"Ahch-To","rarity":"rare","id":"ahch-to","subtitle":"Planets & Locations","details":"An ocean world dotted with rocky islands, Ahch-To held the first Jedi Temple and the ancient texts Luke Skywalker guarded in his exile.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/04/Ahch-To_TLJTVD.png/revision/latest/scale-to-width-down/600?cb=20251031041236"},{"name":"Exegol","rarity":"rare","id":"exegol","subtitle":"Planets & Locations","details":"A dark, storm-shrouded Sith world in the Unknown Regions, Exegol hid Palpatine's return, a Sith cult and a fleet of planet-killing Star Destroyers.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/40/Exegol-TROSTGG.png/revision/latest/scale-to-width-down/600?cb=20250131030648"},{"name":"Mandalore","rarity":"rare","id":"mandalore","subtitle":"Planets & Locations","details":"Homeworld of the Mandalorian people, Mandalore was scarred by wars, ruled from domed cities, and tied to the Darksaber and beskar armor.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/34/Mandalore-2025ToppsSWHyperspace.png/revision/latest/scale-to-width-down/600?cb=20260219064951"},{"name":"Kamino","rarity":"rare","id":"kamino","subtitle":"Planets & Locations","details":"A stormy ocean world beyond the Outer Rim, Kamino's cloners built the Grand Army of the Republic in vast stilt cities above endless seas.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/1c/Kamino-SWCT.png/revision/latest/scale-to-width-down/600?cb=20251031043524"},{"name":"Geonosis","rarity":"rare","id":"geonosis","subtitle":"Planets & Locations","details":"A rocky, ringed desert world of insectoid Geonosians, Geonosis hosted droid foundries and the first great battle of the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/6d/Geonosis_AotC.png/revision/latest/scale-to-width-down/600?cb=20121231120327"},{"name":"Vader's Lightsaber","rarity":"rare","id":"vaders-lightsaber","subtitle":"Weapons, Artifacts & Tech","details":"Darth Vader built his red-bladed lightsaber after falling to the dark side, replacing the blue weapon he wielded as Anakin Skywalker, a Jedi Knight.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8e/VadersLightsaber-DB.png/revision/latest/scale-to-width-down/600?cb=20221116043952"},{"name":"Obi-Wan's Lightsaber","rarity":"rare","id":"obi-wans-lightsaber","subtitle":"Weapons, Artifacts & Tech","details":"Obi-Wan Kenobi carried several lightsabers across his life, and his blue-bladed weapon dueled Darth Vader on the first Death Star in their final meeting.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/7b/KenobiThirdLightsaber-DB.png/revision/latest/scale-to-width-down/600?cb=20251213061329"},{"name":"Mace Windu's Purple Lightsaber","rarity":"rare","id":"mace-windus-purple-lightsaber","subtitle":"Weapons, Artifacts & Tech","details":"Mace Windu's lightsaber burned with a rare purple blade, a distinctive color among the Jedi Order that set the senior Council member apart in battle.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/1a/MaceWinduLightsaber-SWCT.png/revision/latest/scale-to-width-down/600?cb=20251213061520"},{"name":"Count Dooku's Curved Lightsaber","rarity":"rare","id":"count-dookus-curved-lightsaber","subtitle":"Weapons, Artifacts & Tech","details":"Count Dooku wielded a red lightsaber with a curved hilt, a design suited to his refined fencing style and precise, elegant dueling against Jedi Knights.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/03/CountDookusLightsaber-DB.png/revision/latest/scale-to-width-down/600?cb=20230409213029"},{"name":"Double-Bladed Lightsaber","rarity":"rare","id":"double-bladed-lightsaber","subtitle":"Weapons, Artifacts & Tech","details":"Darth Maul introduced the double-bladed lightsaber on screen, spinning its twin red blades against Qui-Gon Jinn and Obi-Wan Kenobi in the duel on Naboo.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d5/Darth_Maul_Lightsaber_DB.png/revision/latest/scale-to-width-down/600?cb=20231227015442"},{"name":"Wampa","rarity":"rare","id":"wampa","subtitle":"Creatures & Species","details":"A hulking, fur-covered predator of Hoth, the wampa dragged Luke Skywalker to its icy cave after striking him from his tauntaun in the frozen wastes.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d0/SkywalkerWampa.jpg/revision/latest?cb=20061124141157"},{"name":"Bantha","rarity":"rare","id":"bantha","subtitle":"Creatures & Species","details":"Banthas are massive, horned herd animals of Tatooine, ridden by Tusken Raiders and valued for their strength, shaggy hides, and rich blue milk.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/42/Bantha-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20241124020931"},{"name":"Rancor","rarity":"rare","id":"rancor","subtitle":"Creatures & Species","details":"The rancor kept beneath Jabba the Hutt's palace was a towering, clawed beast fed unfortunate prisoners, until Luke Skywalker trapped it under a falling gate.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8c/Rancor-SWE.png/revision/latest?cb=20160913053623"},{"name":"Sarlacc","rarity":"rare","id":"sarlacc","subtitle":"Creatures & Species","details":"The sarlacc of Tatooine is a vast, tentacled creature buried in the Great Pit of Carkoon, digesting its prey slowly inside a beaked, tooth-lined maw.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fd/Sarlacc-BTM-DB.png/revision/latest/scale-to-width-down/600?cb=20130401044241"},{"name":"Star Wars: Episode I – The Phantom Menace","rarity":"rare","id":"star-wars-episode-i-the-phantom-menace","subtitle":"Films & Series","details":"Episode I introduced young Anakin Skywalker, podracing on Tatooine, the Sith Darth Maul, and Queen Amidala's fight to free her homeworld of Naboo.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/75/EPI_TPM_poster.png/revision/latest/scale-to-width-down/600?cb=20250617214241"},{"name":"Star Wars: Episode III – Revenge of the Sith","rarity":"rare","id":"star-wars-episode-iii-revenge-of-the-sith","subtitle":"Films & Series","details":"Episode III completed Anakin Skywalker's fall, as Palpatine issued Order 66, the Jedi Order fell, and Darth Vader rose amid the birth of the Empire.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e7/EPIII_RotS_poster.png/revision/latest/scale-to-width-down/600?cb=20250617231154"},{"name":"Rogue One: A Star Wars Story","rarity":"rare","id":"rogue-one-a-star-wars-story","subtitle":"Films & Series","details":"Rogue One followed Jyn Erso and a band of Rebels who stole the Death Star plans on Scarif, setting up the opening moments of A New Hope directly.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/59/RogueOne-AStarWarsStory-Theatricalposter.png/revision/latest/scale-to-width-down/600?cb=20161012214043"},{"name":"The Mandalorian","rarity":"rare","id":"the-mandalorian","subtitle":"Films & Series","details":"The Mandalorian followed bounty hunter Din Djarin as he protected Grogu, a Force-sensitive foundling pursued by remnants of the fallen Galactic Empire.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/45/TheMandalorianS1Poster.png/revision/latest/scale-to-width-down/600?cb=20190823131948"},{"name":"Battle of Endor","rarity":"rare","id":"battle-of-endor","subtitle":"Battles & Iconic Moments","details":"At the Battle of Endor, the Rebel Alliance and the Ewoks destroyed the second Death Star, while Luke confronted Darth Vader and Emperor Palpatine.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/cc/BattleOverEndor-RotJAVA.png/revision/latest/scale-to-width-down/600?cb=20250325043022"},{"name":"Battle of Scarif","rarity":"rare","id":"battle-of-scarif","subtitle":"Battles & Iconic Moments","details":"The Battle of Scarif cost the Rogue One team their lives, but their sacrifice transmitted the Death Star plans to Princess Leia and the Rebel fleet.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/ce/Rebel_Fleet_above_Scarif.jpg/revision/latest/scale-to-width-down/600?cb=20161221014000"},{"name":"Duel on Mustafar","rarity":"rare","id":"duel-on-mustafar","subtitle":"Battles & Iconic Moments","details":"On Mustafar, Obi-Wan Kenobi dueled Anakin Skywalker across rivers of lava, leaving his fallen friend grievously wounded beside a molten riverbank.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e1/DuelonMustafar-TSWB.png/revision/latest/scale-to-width-down/600?cb=20260424040505"},{"name":"Battle of Geonosis","rarity":"rare","id":"battle-of-geonosis","subtitle":"Battles & Iconic Moments","details":"The Battle of Geonosis opened the Clone Wars, as Jedi and a new clone army fought Count Dooku's Separatist forces in the arena and desert plains.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e4/Battle_of_Geonosis.png/revision/latest/scale-to-width-down/600?cb=20170325151752"},{"name":"Battle of Naboo","rarity":"rare","id":"battle-of-naboo","subtitle":"Battles & Iconic Moments","details":"The Battle of Naboo united Naboo's people and the Gungans against the Trade Federation, while Anakin destroyed the droid control ship in orbit.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/04/Gunganarmy.jpg/revision/latest/scale-to-width-down/600?cb=20110917124938"},{"name":"Zeb Orrelios","rarity":"uncommon","id":"zeb-orrelios","subtitle":"Heroes & Rebels","details":"Garazeb 'Zeb' Orrelios, a Lasat honor guardsman, served as the Ghost crew's muscle, fighting the Empire with his bo-rifle and a gruff sense of humor.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/59/ZebOrrelios-TMGPremiere.png/revision/latest?cb=20260523150814"},{"name":"Hondo Ohnaka","rarity":"uncommon","id":"hondo-ohnaka","subtitle":"Heroes & Rebels","details":"Hondo Ohnaka, a flamboyant Weequay pirate, crossed paths with Jedi, Sith, and Rebels alike, always chasing profit and talking his way out of trouble.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b8/HondoOhnaka-TGTB.png/revision/latest?cb=20251217184604"},{"name":"Bo-Katan Kryze","rarity":"uncommon","id":"bo-katan-kryze","subtitle":"Heroes & Rebels","details":"Bo-Katan Kryze, a Mandalorian warrior of House Kryze, fought to free Mandalore and later wielded the Darksaber in the struggle to unite her people.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/ec/BoKatanKryze-TTG2024.png/revision/latest?cb=20251118053437"},{"name":"Fennec Shand","rarity":"uncommon","id":"fennec-shand","subtitle":"Heroes & Rebels","details":"Fennec Shand, an elite mercenary and sharpshooter, survived a wound on Tatooine thanks to Boba Fett and became his trusted partner and enforcer.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/03/FennecShandHeadshot-BOBFCE.png/revision/latest/scale-to-width-down/600?cb=20250524021217"},{"name":"Cara Dune","rarity":"uncommon","id":"cara-dune","subtitle":"Heroes & Rebels","details":"Cara Dune, a former Rebel shock trooper from Alderaan, became a marshal on Nevarro and fought beside Din Djarin against Imperial remnants there.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/32/CaraDuneS2-EW.png/revision/latest/scale-to-width-down/600?cb=20200909003912"},{"name":"Greef Karga","rarity":"uncommon","id":"greef-karga","subtitle":"Heroes & Rebels","details":"Greef Karga led the Bounty Hunters' Guild on Nevarro, hired Din Djarin for the Grogu job, and later became the planet's respected High Magistrate.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3e/GreefKarga-ToppsFinest2023.png/revision/latest?cb=20251123230318"},{"name":"Depa Billaba","rarity":"uncommon","id":"depa-billaba","subtitle":"Heroes & Rebels","details":"Jedi Master Depa Billaba served on the Jedi Council and trained Padawan Caleb Dume, who survived Order 66 to become Kanan Jarrus of the Ghost crew.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/dd/DepaBillaba-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20250501055014"},{"name":"Adi Gallia","rarity":"uncommon","id":"adi-gallia","subtitle":"Heroes & Rebels","details":"Jedi Master Adi Gallia, a skilled pilot and Council member, fought in the Clone Wars until she was killed by Savage Opress during the conflict.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f2/AdiGallia2-SWE.png/revision/latest/scale-to-width-down/600?cb=20240922163922"},{"name":"Even Piell","rarity":"uncommon","id":"even-piell","subtitle":"Heroes & Rebels","details":"Even Piell, a small Lannik Jedi Master on the Council, was captured during the Clone Wars and died passing vital hyperspace route secrets to his allies.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/ea/EvenPiellInfobox-SWE.png/revision/latest/scale-to-width-down/600?cb=20240209023854"},{"name":"Yaddle","rarity":"uncommon","id":"yaddle","subtitle":"Heroes & Rebels","details":"Yaddle, a long-lived Jedi Master of the same species as Yoda, served on the Jedi Council during the era of The Phantom Menace and trained many Jedi.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/7f/Yaddle-SWCT.png/revision/latest?cb=20241228210308"},{"name":"Oppo Rancisis","rarity":"uncommon","id":"oppo-rancisis","subtitle":"Heroes & Rebels","details":"Oppo Rancisis, a serpentine Thisspiasian Jedi Master, served on the Jedi Council and was famed for his wisdom, long beard, and battle meditation.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/70/OppoRancisis-2026ToppsChromeSW.png/revision/latest/scale-to-width-down/600?cb=20261010214706"},{"name":"Saesee Tiin","rarity":"uncommon","id":"saesee-tiin","subtitle":"Heroes & Rebels","details":"Saesee Tiin, a horned Iktotchi Jedi Master and expert pilot, served on the Council and fell when he confronted Chancellor Palpatine as a Sith Lord.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a3/SaeseeTiin-SWCT.png/revision/latest?cb=20251129194602"},{"name":"Eeth Koth","rarity":"uncommon","id":"eeth-koth","subtitle":"Heroes & Rebels","details":"Eeth Koth, a Zabrak Jedi Master on the Council, fought in the Clone Wars and was captured by General Grievous before being rescued by fellow Jedi.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/57/EethKoth-TheJediCouncil.png/revision/latest?cb=20260105023333"},{"name":"Agen Kolar","rarity":"uncommon","id":"agen-kolar","subtitle":"Heroes & Rebels","details":"Agen Kolar, a Zabrak Jedi Master famed for his skill with a lightsaber, fell beside Mace Windu when the Jedi confronted Chancellor Palpatine.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c9/AgenKolar-TheJediCouncil.png/revision/latest?cb=20260105020147"},{"name":"Stass Allie","rarity":"uncommon","id":"stass-allie","subtitle":"Heroes & Rebels","details":"Stass Allie, a Jedi Master and skilled healer, served during the Clone Wars and was killed by her own clone troopers while riding on Saleucami.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c3/StassAllie-OP.png/revision/latest/scale-to-width-down/600?cb=20241217024905"},{"name":"Coleman Trebor","rarity":"uncommon","id":"coleman-trebor","subtitle":"Heroes & Rebels","details":"Coleman Trebor, a tall Vurk Jedi Master, leapt to strike Count Dooku in the Geonosis arena but was shot down by Jango Fett before he could land a blow.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f2/ColemanTrebor-DB.png/revision/latest/scale-to-width-down/600?cb=20150920194631"},{"name":"Bultar Swan","rarity":"uncommon","id":"bultar-swan","subtitle":"Heroes & Rebels","details":"Bultar Swan, a Jedi Knight skilled in unarmed combat, fought in the arena on Geonosis and survived the opening battle of the Clone Wars conflict.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/0c/BultarSwan-VisualEncyclopedia.png/revision/latest?cb=20220316193538"},{"name":"Jocasta Nu","rarity":"uncommon","id":"jocasta-nu","subtitle":"Heroes & Rebels","details":"Jocasta Nu was the chief librarian of the Jedi Archives on Coruscant, fiercely protective of its records and certain of the wisdom they held.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/ca/JocastaNu-TCWCEJtB.png/revision/latest/scale-to-width-down/600?cb=20240204065141"},{"name":"Korkie Kryze","rarity":"uncommon","id":"korkie-kryze","subtitle":"Heroes & Rebels","details":"Korkie Kryze, nephew of Duchess Satine and Bo-Katan, studied at Mandalore's Royal Academy and helped expose corruption in the planet's government.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e7/KorkieKryzeFull-TCWCEJtB.png/revision/latest/scale-to-width-down/600?cb=20260221023132"},{"name":"Satine Kryze","rarity":"uncommon","id":"satine-kryze","subtitle":"Heroes & Rebels","details":"Duchess Satine Kryze led Mandalore as a committed pacifist, resisting the Death Watch and holding a complicated history with Obi-Wan Kenobi.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/ce/DuchessSatineThrone.png/revision/latest/scale-to-width-down/600?cb=20210217153235"},{"name":"General Veers","rarity":"uncommon","id":"general-veers","subtitle":"Villains & Empire","details":"General Maximilian Veers commanded the Imperial walkers in the assault on Echo Base, leading the AT-AT force that broke the Rebels' shield defenses on Hoth.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/7f/Armored_Veers_full.png/revision/latest/scale-to-width-down/600?cb=20231029183644"},{"name":"Admiral Ozzel","rarity":"uncommon","id":"admiral-ozzel","subtitle":"Villains & Empire","details":"Admiral Ozzel commanded Darth Vader's flagship, but his blunder bringing the fleet out of hyperspace too close to Hoth earned him a fatal Force choke.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b1/Ozzel_croaks.jpg/revision/latest/scale-to-width-down/600?cb=20120104152652"},{"name":"Captain Needa","rarity":"uncommon","id":"captain-needa","subtitle":"Villains & Empire","details":"Captain Needa commanded the Star Destroyer Avenger and personally apologized to Darth Vader after losing the Millennium Falcon, at fatal cost.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/82/CaptainNeeda-SWZ.png/revision/latest/scale-to-width-down/600?cb=20210105020321"},{"name":"Moff Jerjerrod","rarity":"uncommon","id":"moff-jerjerrod","subtitle":"Villains & Empire","details":"Moff Jerjerrod oversaw construction of the second Death Star, nervously reporting its delays to Darth Vader and Emperor Palpatine at Endor's moon.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/15/Moff_Jerjerrod_2.jpg/revision/latest/scale-to-width-down/600?cb=20120111033308"},{"name":"General Hux","rarity":"uncommon","id":"general-hux","subtitle":"Villains & Empire","details":"General Armitage Hux, a fanatical First Order officer, commanded Starkiller Base's firing on the Hosnian system and rivaled Kylo Ren for power.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/eb/ArmitageHux-TFApromo.png/revision/latest/scale-to-width-down/600?cb=20230221004911"},{"name":"Captain Phasma","rarity":"uncommon","id":"captain-phasma","subtitle":"Villains & Empire","details":"Captain Phasma commanded First Order stormtroopers in gleaming chromium armor made from a yacht once owned by Emperor Palpatine himself.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b0/CaptainPhasma.png/revision/latest/scale-to-width-down/600?cb=20160107200143"},{"name":"Allegiant General Pryde","rarity":"uncommon","id":"allegiant-general-pryde","subtitle":"Villains & Empire","details":"Allegiant General Enric Pryde, a veteran Imperial officer, served the First Order and then commanded the Sith Eternal fleet above Exegol.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/37/Pryde-_Entertainment_Weekly.jpg/revision/latest/scale-to-width-down/600?cb=20191119204525"},{"name":"Bib Fortuna","rarity":"uncommon","id":"bib-fortuna","subtitle":"Villains & Empire","details":"Bib Fortuna, Jabba the Hutt's Twi'lek majordomo, greeted visitors at the palace on Tatooine and briefly fell under Luke Skywalker's Jedi mind trick.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/31/Bib_TPM.png/revision/latest/scale-to-width-down/600?cb=20120727183442"},{"name":"Salacious Crumb","rarity":"uncommon","id":"salacious-crumb","subtitle":"Villains & Empire","details":"Salacious B. Crumb, a Kowakian monkey-lizard, was Jabba the Hutt's cackling court jester, perched beside the crime lord and mocking his victims.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/4d/Crumb_btm.png/revision/latest/scale-to-width-down/600?cb=20160910042918"},{"name":"Oola","rarity":"uncommon","id":"oola","subtitle":"Villains & Empire","details":"Oola, a Twi'lek dancer in Jabba the Hutt's palace, defied her captor during a performance and was fed to the rancor beneath the throne room floor.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a7/OolaGargan-Dancing-ROTJ.png/revision/latest/scale-to-width-down/600?cb=20220507081128"},{"name":"Tobias Beckett","rarity":"uncommon","id":"tobias-beckett","subtitle":"Villains & Empire","details":"Tobias Beckett, a seasoned outlaw and gunslinger, mentored young Han Solo in a train heist and a Kessel coaxium job before betraying him for profit.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c0/BeckettImperial-SoloOMG.png/revision/latest/scale-to-width-down/600?cb=20231103012703"},{"name":"Qi'ra","rarity":"uncommon","id":"qira","subtitle":"Villains & Empire","details":"Qi'ra grew up with Han Solo on Corellia, rose within the Crimson Dawn crime syndicate, and chose its power over escaping with him from a hard life.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/84/QiraDress-SoloOMG.png/revision/latest/scale-to-width-down/600?cb=20260125011000"},{"name":"Morgan Elsbeth","rarity":"uncommon","id":"morgan-elsbeth","subtitle":"Villains & Empire","details":"Morgan Elsbeth, a Nightsister ally of Grand Admiral Thrawn, ruled Calodan on Corvus and fought Ahsoka Tano with a spear of pure beskar steel.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/dc/MorganElsbethfull-SWI207.png/revision/latest/scale-to-width-down/600?cb=20250912133919"},{"name":"Fifth Brother","rarity":"uncommon","id":"fifth-brother","subtitle":"Villains & Empire","details":"The Fifth Brother was an Inquisitor tasked with hunting Jedi survivors, pursuing Kanan Jarrus and Ezra Bridger alongside the Seventh Sister.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/94/FifthBrotherInquisitor-ChromeBlack2024.png/revision/latest/scale-to-width-down/600?cb=20251211065800"},{"name":"B1 Battle Droid","rarity":"uncommon","id":"b1-battle-droid","subtitle":"Droids","details":"B1 battle droids formed the backbone of the Separatist army, cheap, clumsy, and chatty infantry that fought in vast numbers during the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c0/Rust_brown_B1_battle_droid.png/revision/latest/scale-to-width-down/600?cb=20190626220213"},{"name":"B2 Super Battle Droid","rarity":"uncommon","id":"b2-super-battle-droid","subtitle":"Droids","details":"B2 super battle droids were sturdier Separatist infantry with built-in wrist blasters, shrugging off hits that would drop a standard B1 battle droid.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/45/B2Lineup-SWE.png/revision/latest/scale-to-width-down/600?cb=20230708234009"},{"name":"Droideka","rarity":"uncommon","id":"droideka","subtitle":"Droids","details":"Droidekas, or destroyer droids, rolled into battle and unfolded into tripod gun platforms protected by their own deflector shield generators.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/75/Droideka-USC.png/revision/latest/scale-to-width-down/600?cb=20190604143936"},{"name":"Magnaguard","rarity":"uncommon","id":"magnaguard","subtitle":"Droids","details":"MagnaGuards were elite droids that protected General Grievous and Separatist leaders, fighting Jedi with electrostaffs even after losing limbs or heads.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/eb/MagnaGuard-CN.png/revision/latest/scale-to-width-down/600?cb=20230712035352"},{"name":"Pit Droid","rarity":"uncommon","id":"pit-droid","subtitle":"Droids","details":"Pit droids are small, tireless repair workers seen in podracing pits and workshops, folding flat when struck on the nose and springing back up again.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/81/PitDroid-Db.png/revision/latest/scale-to-width-down/600?cb=20240918014058"},{"name":"Astromech Droid","rarity":"uncommon","id":"astromech-droid","subtitle":"Droids","details":"Astromech droids like R2-D2 service starfighters, store hyperspace coordinates, and carry out repairs, communications, and the occasional heroic rescue.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/43/AstroDroids-PoeDameron20.png/revision/latest/scale-to-width-down/600?cb=20190106072251"},{"name":"Protocol Droid","rarity":"uncommon","id":"protocol-droid","subtitle":"Droids","details":"Protocol droids like C-3PO specialize in etiquette, translation, and diplomacy, fluent in millions of forms of communication across the galaxy.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/63/C-3PO-SWLRulesRef.png/revision/latest/scale-to-width-down/600?cb=20240828045619"},{"name":"Mouse Droid","rarity":"uncommon","id":"mouse-droid","subtitle":"Droids","details":"Mouse droids are small, wheeled Imperial droids that scurry across Star Destroyer decks carrying messages, squealing and fleeing when startled.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/af/MSE-6_Mouse_Droid.jpg/revision/latest/scale-to-width-down/600?cb=20251019183659"},{"name":"TIE Bomber","rarity":"uncommon","id":"tie-bomber","subtitle":"Starships & Vehicles","details":"The TIE bomber carried heavy ordnance in its twin hull, delivering proton bombs against Rebel ships, bases, and hiding places with Imperial precision.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/17/TIE_Bomber_BF2.png/revision/latest/scale-to-width-down/600?cb=20230720014331"},{"name":"TIE Advanced x1","rarity":"uncommon","id":"tie-advanced-x1","subtitle":"Starships & Vehicles","details":"Darth Vader flew the TIE Advanced x1, a prototype with deflector shields and a hyperdrive, during the Battle of Yavin against Rebel starfighters.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c7/Rebels_TIE_Advanced_x1_Fathead.png/revision/latest/scale-to-width-down/600?cb=20180116012130"},{"name":"Lambda-Class Shuttle","rarity":"uncommon","id":"lambda-class-shuttle","subtitle":"Starships & Vehicles","details":"The Lambda-class shuttle, with its tri-wing design, carried Imperial officers, troops, and even Emperor Palpatine between ships and planetary surfaces.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/62/LambdaShuttleDocked-Fathead.png/revision/latest/scale-to-width-down/600?cb=20230802044015"},{"name":"Sentinel Landing Craft","rarity":"uncommon","id":"sentinel-landing-craft","subtitle":"Starships & Vehicles","details":"The Sentinel-class landing craft is a heavily armed Imperial troop transport, larger than a Lambda shuttle and built to deliver forces under fire.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8c/Sentinel_class_shuttle-SWC.png/revision/latest/scale-to-width-down/600?cb=20161001005615"},{"name":"GR-75 Transport","rarity":"uncommon","id":"gr-75-transport","subtitle":"Starships & Vehicles","details":"GR-75 medium transports carried Rebel personnel and supplies, forming the evacuation convoy that escaped the Imperial assault on Hoth's Echo Base.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8c/RebelTransport-Fathead.png/revision/latest/scale-to-width-down/600?cb=20230802042532"},{"name":"CR90 Corvette","rarity":"uncommon","id":"cr90-corvette","subtitle":"Starships & Vehicles","details":"The CR90 corvette Tantive IV carried Princess Leia and the stolen Death Star plans, becoming the first starship seen on screen in the original film.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/38/Corvette_negvv.png/revision/latest/scale-to-width-down/600?cb=20170410043658"},{"name":"Nebulon-B Frigate","rarity":"uncommon","id":"nebulon-b-frigate","subtitle":"Starships & Vehicles","details":"The Nebulon-B frigate served the Rebel fleet as an escort and medical ship, its long spar connecting engines to a cluster of habitat modules.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/66/Vanguard-RitR.png/revision/latest/scale-to-width-down/600?cb=20191021004758"},{"name":"MC75 Star Cruiser","rarity":"uncommon","id":"mc75-star-cruiser","subtitle":"Starships & Vehicles","details":"The MC75 star cruiser Raddus served as Admiral Raddus's flagship at Scarif, carrying the Rebel command during the desperate fight for the plans.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/99/MC75-SWS.png/revision/latest/scale-to-width-down/600?cb=20210303024415"},{"name":"Resurgent Star Destroyer","rarity":"uncommon","id":"resurgent-star-destroyer","subtitle":"Starships & Vehicles","details":"The Resurgent-class Star Destroyer was the First Order's capital ship, larger and more heavily armed than the Imperial Star Destroyers before it.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2b/StarDestroyerFlythrough.jpg/revision/latest/scale-to-width-down/600?cb=20210507113234"},{"name":"First Order Dreadnought","rarity":"uncommon","id":"first-order-dreadnought","subtitle":"Starships & Vehicles","details":"The First Order dreadnought Fulminatrix carried massive orbital bombardment cannons, destroyed by Poe Dameron's daring run during the Resistance escape.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/75/FO_Mandator_Dreadnought_ICS.png/revision/latest/scale-to-width-down/600?cb=20180116055226"},{"name":"U-Wing Starfighter","rarity":"uncommon","id":"u-wing-starfighter","subtitle":"Starships & Vehicles","details":"A Rebel troop transport and gunship with swing wings, the U-wing carried Cassian Andor's team to Scarif and fought in the space battle above it.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b1/StarWarswebsite-U-Wing.png/revision/latest/scale-to-width-down/600?cb=20230802002741"},{"name":"TIE Defender","rarity":"uncommon","id":"tie-defender","subtitle":"Starships & Vehicles","details":"An advanced Imperial fighter with triple wings, shields, and heavy cannons, the TIE Defender was Grand Admiral Thrawn's prized Lothal project.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/44/SWB_TIE_Defender.png/revision/latest/scale-to-width-down/600?cb=20230723015418"},{"name":"T-70 X-Wing","rarity":"uncommon","id":"t-70-x-wing","subtitle":"Starships & Vehicles","details":"The Resistance's main starfighter, the faster T-70 X-wing carried Poe Dameron and his Black Squadron pilots into battle against the First Order.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/ee/T70XwingStarfighter-SWBC41.png/revision/latest/scale-to-width-down/600?cb=20241013174128"},{"name":"RZ-2 A-Wing","rarity":"uncommon","id":"rz-2-a-wing","subtitle":"Starships & Vehicles","details":"A lightning-fast Resistance interceptor, the RZ-2 A-wing relied on speed and agility, flown by pilots like Tallie Lintra at the Battle of D'Qar.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b8/RZ2Awing-TLJTOG.png/revision/latest/scale-to-width-down/600?cb=20240327185029"},{"name":"MG-100 StarFortress Bomber","rarity":"uncommon","id":"mg-100-starfortress-bomber","subtitle":"Starships & Vehicles","details":"A lumbering Resistance heavy bomber, the MG-100 StarFortress dropped racks of proton bombs, as Paige Tico's crew did over a First Order dreadnought.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/5a/MG-100_Starfortress.png/revision/latest/scale-to-width-down/450?cb=20230813062536"},{"name":"Ski Speeder","rarity":"uncommon","id":"ski-speeder","subtitle":"Starships & Vehicles","details":"Resistance ski speeders skimmed Crait's salt flats on a single stabilizer ski, kicking up red dust as they charged the First Order's siege cannon.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/ad/V-4X-D_Ski_Speeder_TLJ.png/revision/latest/scale-to-width-down/600?cb=20230513145421"},{"name":"AT-M6 Walker","rarity":"uncommon","id":"at-m6-walker","subtitle":"Starships & Vehicles","details":"The First Order's massive All Terrain MegaCaliber Six walker carried a heavy turbolaser cannon on its back during the ground assault on Crait.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/cf/AT-M6.png/revision/latest/scale-to-width-down/548?cb=20230813060340"},{"name":"AT-Hauler","rarity":"uncommon","id":"at-hauler","subtitle":"Starships & Vehicles","details":"Imperial All Terrain Haulers airlifted cargo and AT-DT walkers by cable, hauling the coaxium shipment target during the train heist on Vandor.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fd/AThauler-SASWSOCE.png/revision/latest/scale-to-width-down/600?cb=20231222010824"},{"name":"Yavin 4","rarity":"uncommon","id":"yavin-4","subtitle":"Planets & Locations","details":"A jungle moon orbiting the gas giant Yavin, Yavin 4 hid the Rebel Alliance base inside ancient Massassi temples before the first Death Star battle.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d4/Yavin-4-SWCT.png/revision/latest/scale-to-width-down/600?cb=20181015023938"},{"name":"Kashyyyk","rarity":"uncommon","id":"kashyyyk","subtitle":"Planets & Locations","details":"Homeworld of the Wookiees, Kashyyyk's towering wroshyr trees held cities in their branches, and its beaches became a late Clone Wars battleground.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/ea/Kashyyyk-SW-MTHC.png/revision/latest/scale-to-width-down/600?cb=20251122015233"},{"name":"Felucia","rarity":"uncommon","id":"felucia","subtitle":"Planets & Locations","details":"A humid jungle world of giant fungi and translucent plants, Felucia saw repeated Clone Wars battles and Aayla Secura's final mission in Order 66.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a2/Felucia_SWCT.png/revision/latest/scale-to-width-down/600?cb=20181010054430"},{"name":"Mygeeto","rarity":"uncommon","id":"mygeeto","subtitle":"Planets & Locations","details":"A cold, ash-covered banking world, Mygeeto was fought over late in the Clone Wars, where Ki-Adi-Mundi led clone marines across its crystal bridges.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/13/Mygeeto-GalaxysEdge2.jpg/revision/latest/scale-to-width-down/600?cb=20190525003238"},{"name":"Utapau","rarity":"uncommon","id":"utapau","subtitle":"Planets & Locations","details":"A remote world pocked with vast sinkhole cities, Utapau sheltered General Grievous until Obi-Wan Kenobi tracked him there near the Clone Wars' end.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/ce/UtapauRotS.png/revision/latest/scale-to-width-down/600?cb=20160118063015"},{"name":"Cato Neimoidia","rarity":"uncommon","id":"cato-neimoidia","subtitle":"Planets & Locations","details":"A wealthy Neimoidian colony of bridge cities spanning rocky pillars, Cato Neimoidia appeared in the Clone Wars and in Plo Koon's final flight.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fe/CatoNeimoidia-BTCG.png/revision/latest/scale-to-width-down/600?cb=20211111010658"},{"name":"Christophsis","rarity":"uncommon","id":"christophsis","subtitle":"Planets & Locations","details":"A crystalline world of blue-green spires, Christophsis was invaded by Separatists and defended by Anakin Skywalker, Obi-Wan Kenobi, and young Ahsoka.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/30/Christophsis.jpg/revision/latest/scale-to-width-down/600?cb=20200408094217"}]});
